from pysat.formula import CNF
from pysat.card import CardEnc, EncType
from pysat.solvers import Glucose3, Cadical153, Minisat22
W=5; P=21; G=7

def var(w,p,g): return 1 + (w*P+p)*G+g
cnf=CNF()
top=W*P*G
# each player exactly one group per week
for w in range(W):
  for p in range(P):
    lits=[var(w,p,g) for g in range(G)]
    cnf.append(lits)
    for i in range(G):
      for j in range(i+1,G): cnf.append([-lits[i],-lits[j]])
# each group exactly 3 players per week
for w in range(W):
  for g in range(G):
    lits=[var(w,p,g) for p in range(P)]
    enc=CardEnc.equals(lits, bound=3, top_id=top, encoding=EncType.seqcounter)
    cnf.extend(enc.clauses); top=enc.nv
# no pair meets more than once
for p in range(P):
  for q in range(p+1,P):
    for w1 in range(W):
      for w2 in range(w1+1,W):
        for g1 in range(G):
          for g2 in range(G):
            cnf.append([-var(w1,p,g1),-var(w1,q,g1),-var(w2,p,g2),-var(w2,q,g2)])
# symmetry fix week0: group floor(p/3)
for p in range(P):
  cnf.append([var(0,p,p//3)])
